 expect(env.OPENAI_API_KEY).toBeUndefined();expect(env.CODEX_API_KEY).toBeUndefined();expect(env.OPENAI_BASE_URL).toBeUndefined();expect(env.NODE_OPTIONS).toBeUndefined();
