85	  const seat = (panel && panel.seats || []).at(-1);
86	  const rawVerdict = seat && seat.status === 'succeeded'
87	    && typeof seat.answer === 'string' && seat.answer.trim()
88	    ? seat.parsed && seat.parsed.verdict : null;
89	  return {
90	    verdict: !seat || seat.status !== 'succeeded' ? 'review_incomplete'
91	      : !rawVerdict ? 'no_claim'
92	        : rawVerdict,
93	    rawVerdict: rawVerdict || null,
94	    reviewer: seat ? seat.id : null,
95	    sequence: seat ? seat.sequence : null,
96	    answerSha256: seat && seat.answer
97	      ? crypto.createHash('sha256').update(seat.answer).digest('hex') : null,
98	    basis: 'reviewer report; not certification',
99	  };
100	}
