102	function parseReviewerSelection(value) {
103	  const parts = String(value == null ? '' : value)
104	    .split(',')
105	    .map(part => part.trim().toLowerCase());
106	  if (parts.length === 0 || parts.some(part => part === '')) {
107	    throw new Error('--reviewers requires at least one reviewer');
108	  }
109	  const selected = [];
110	  for (const id of parts) {
111	    if (!REVIEWERS_BY_ID.has(id)) {
112	      throw new Error(`Unknown reviewer "${id}"; choose from ${REVIEWER_REGISTRY.map(item => item.id).join(',')}`);
113	    }
114	    if (!selected.includes(id)) selected.push(id);
115	  }
116	  return selected;
117	}
118	
119	function selectionReceipt(selected, { requested = null, source }) {
120	  return {
121	    requested,
122	    selected,
123	    unselected: REVIEWER_REGISTRY.map(reviewer => reviewer.id).filter(id => !selected.includes(id)),
124	    source,
125	  };
126	}
127	
128	async function resolveReviewerSelection({
129	  explicit = null,
130	  interactive = false,
131	  prompt = null,
132	  defaultReviewers = ['mercury'],
133	} = {}) {
134	  if (explicit !== null) {
135	    const selected = parseReviewerSelection(explicit);
136	    return selectionReceipt(selected, { requested: selected, source: 'explicit' });
137	  }
138	  if (interactive) {
139	    if (typeof prompt !== 'function') {
140	      throw new Error('Interactive reviewer selection requires a prompt implementation');
141	    }
142	    const response = await prompt({
143	      message: 'Select reviewers for this adversarial run',
144	      choices: REVIEWER_REGISTRY,
145	    });
146	    const selected = Array.isArray(response)
147	      ? parseReviewerSelection(response.join(','))
148	      : parseReviewerSelection(response);
149	    return selectionReceipt(selected, { requested: selected, source: 'interactive' });
150	  }
151	  const selected = parseReviewerSelection(defaultReviewers.join(','));
152	  return selectionReceipt(selected, { source: 'configured_default' });
153	}
154	
155	async function promptReviewerSelection({ message, choices }, {
156	  input = process.stdin,
157	  output = process.stdout,
158	} = {}) {
159	  output.write(`${message}\n`);
160	  choices.forEach((choice, index) => output.write(`  ${index + 1}. ${choice.label} (${choice.id})\n`));
161	  const interface_ = readline.createInterface({ input, output });
162	  const answer = await new Promise(resolve => interface_.question(
163	    'Reviewer IDs or numbers (comma-separated): ', resolve
164	  ));
165	  interface_.close();
166	  return answer.split(',').map((item) => {
167	    const value = item.trim();
168	    if (/^\d+$/.test(value)) {
169	      const choice = choices[Number(value) - 1];
170	      return choice ? choice.id : value;
171	    }
172	    return value;
173	  });
174	}
175	
176	function summarizePanelDiagnostics(seats) {
177	  const selectedSeats = seats || [];
178	  const failedSelected = selectedSeats.filter(seat => seat.status !== 'succeeded');
179	  const successful = selectedSeats.filter(seat => (
180	    seat.status === 'succeeded'
181	    && seat.qualifying !== false
182	    && seat.identityConflict !== true
183	  ));
184	  const claimingSeats = successful.filter(seat => seat.verdict !== 'no_claim');
185	  const verdicts = [...new Set(claimingSeats.map((seat) => {
186	    if (['pass', 'no_break_found'].includes(seat.verdict)) return 'pass';
187	    if (['found_break', 'blocked'].includes(seat.verdict)) return 'found_break';
188	    return seat.verdict || 'cannot_verify';
189	  }))];
190	  const agreement = successful.length >= 2 && claimingSeats.length > 0 && verdicts.length === 1;
191	  const evidenceChecksPassed = successful.length > 0
192	    && successful.every(seat => seat.evidenceChecksPassed === true);
193	  const fingerprints = successful.map(seat => seat.effectiveIdentityFingerprint).filter(Boolean);
194	  const identitiesAttested = fingerprints.length === successful.length;
195	  const identitiesIndependent = identitiesAttested && new Set(fingerprints).size === fingerprints.length;
196	  const issues = [];
197	  if (failedSelected.length > 0) issues.push('selected_seat_unavailable');
198	  if (successful.length < 2) issues.push('insufficient_qualifying_seats');
199	  if (selectedSeats.some(seat => seat.identityConflict === true)) issues.push('identity_conflict');
200	  if (!evidenceChecksPassed) issues.push('evidence_failure');
201	  if (successful.length >= 2 && !identitiesIndependent) {
202	    issues.push(identitiesAttested ? 'identity_collision' : 'identity_attestation_absent');
203	  }
204	  if (successful.length >= 2 && claimingSeats.length === 0) issues.push('reviewer_claim_absent');
205	  if (claimingSeats.length > 1 && verdicts.length > 1) issues.push('reviewer_verdict_labels_differ');
206	  return {
207	    qualifyingSeats: successful.length,
208	    verdictLabelsMatch: agreement,
209	    evidenceChecksPassed,
210	    identitiesAttested,
211	    identitiesIndependent,
212	    issues,
213	    sharedVerdictLabel: agreement ? verdicts[0] : null,
214	  };
215	}
216	
217	function ensureReviewerAnswer(result, reviewerId) {
218	  if (result && result.termination === 'answer_given' && String(result.answer || '').trim() !== '') {
219	    return result;
220	  }
221	  const message = String(result && result.answer || `${reviewerId} reviewer answer absent`);
222	  const error = new Error(message);
223	  error.absence = /quota|rate.?limit|HTTP 402|HTTP 429|usage.limit/i.test(message)
224	    ? 'quota_or_rate_limit'
225	    : 'reviewer_answer_absent';
226	  error.reviewerResult = result || null;
227	  throw error;
228	}
