230	async function runReviewerPanel({ selected, runSeat, isHardStop }) {
231	  const seats = [];
232	  for (const id of selected) {
233	    const reviewer = REVIEWERS_BY_ID.get(id);
234	    const sequence = seats.length + 1;
235	    try {
236	      const result = await runSeat(reviewer, seats);
237	      seats.push({
238	        ...result,
239	        id,
240	        label: reviewer.label,
241	        sequence,
242	        status: 'succeeded',
243	        qualifying: result && result.qualifying !== false,
244	      });
245	    } catch (error) {
246	      if (isHardStop(error)) throw error;
247	      seats.push({
248	        id,
249	        label: reviewer.label,
250	        sequence,
251	        status: 'failed',
252	        qualifying: false,
253	        absence: error.absence || 'reviewer_answer_absent',
254	        error,
255	      });
256	    }
257	  }
258	  return { seats, diagnostics: summarizePanelDiagnostics(seats) };
259	}
